/// ``apps/shared/src/slash.ts::parseCommandDispatch`` branches on this.
enum DispatchType {
  exec('exec'),
  alias('alias'),
  plugin('plugin'),
  send('send'),
  skill('skill'),
  prefill('prefill'),

  /// A value this client version does not know.
  $unknown('');

  const DispatchType(this.wire);

  /// The JSON value.
  final String wire;

  /// Decodes [wire]; unknown values map to [$unknown] so newer servers stay readable.
  static DispatchType fromWire(String wire) =>
      values.firstWhere((e) => e.wire == wire, orElse: () => $unknown);
}

