enum InterruptStatus {
  interrupted('interrupted'),
  notInterrupted('not_interrupted'),

  /// A value this client version does not know.
  $unknown('');

  const InterruptStatus(this.wire);

  /// The JSON value.
  final String wire;

  /// Decodes [wire]; unknown values map to [$unknown] so newer servers stay readable.
  static InterruptStatus fromWire(String wire) =>
      values.firstWhere((e) => e.wire == wire, orElse: () => $unknown);
}

