enum PluginServerState {
  connected('connected'),
  appNotRunning('app_not_running'),
  endpointUnavailable('endpoint_unavailable'),
  noInteractiveSession('no_interactive_session'),
  versionTooOld('version_too_old'),
  missingApp('missing_app'),
  unknown('unknown'),

  /// A value this client version does not know.
  $unknown('');

  const PluginServerState(this.wire);

  /// The JSON value.
  final String wire;

  /// Decodes [wire]; unknown values map to [$unknown] so newer servers stay readable.
  static PluginServerState fromWire(String wire) =>
      values.firstWhere((e) => e.wire == wire, orElse: () => $unknown);
}

