enum SkillsAction {
  list('list'),
  search('search'),
  install('install'),
  browse('browse'),
  inspect('inspect'),

  /// A value this client version does not know.
  $unknown('');

  const SkillsAction(this.wire);

  /// The JSON value.
  final String wire;

  /// Decodes [wire]; unknown values map to [$unknown] so newer servers stay readable.
  static SkillsAction fromWire(String wire) =>
      values.firstWhere((e) => e.wire == wire, orElse: () => $unknown);
}

