          final Object v => (v as num).toInt(),
        },
        totalPages: switch (json['total_pages']) {
          null => null,
          final Object v => (v as num).toInt(),
        },
        total: switch (json['total']) {
          null => null,
          final Object v => (v as num).toInt(),
        },
