  final List<SkillHubHit>? results;

  final bool? installed;

  final String? name;

  final List<SkillBrowseItem>? items;

  final int? page;

  final int? totalPages;

  final int? total;

  final SkillInspectInfo? info;

  @override
  Map<String, Object?> toJson() => {
    if (skills != null)
      'skills': {for (final e in skills!.entries) e.key: e.value},
