/// A gateway notification: `{"method": "event", "params": {"type", "session_id", "seq", "payload"}}`.
sealed class HermesEvent {
  const HermesEvent({this.sessionId, this.seq});

  /// Owning session; empty or null for app-level events.
  final String? sessionId;

  /// Per-session monotonic sequence number used by `session.events.since`.
  final int? seq;

  /// The wire `type`.
  String get type;

  /// Decodes the `params` of an `event` frame.
  static HermesEvent fromParams(Map<String, Object?> params) {
    final sessionId = params['session_id'] as String?;
    final seq = (params['seq'] as num?)?.toInt();
    final payload = params['payload'];
    final body = payload is Map<String, Object?>
        ? payload
        : const <String, Object?>{};
    return switch (params['type']) {
      'agent.terminal.output' => AgentTerminalOutputEvent(
        sessionId: sessionId,
        seq: seq,
        payload: TerminalOutputPayload.fromJson(body),
      ),
      'background.complete' => BackgroundCompleteEvent(
        sessionId: sessionId,
        seq: seq,
        payload: SideAgentCompletePayload.fromJson(body),
      ),
      'billing.step_up.verification' => BillingStepUpVerificationEvent(
        sessionId: sessionId,
        seq: seq,
        payload: BillingStepUpVerificationPayload.fromJson(body),
      ),
      'bot_relay.outbox.pending' => BotRelayOutboxPendingEvent(
        sessionId: sessionId,
        seq: seq,
        payload: ChangeSignalPayload.fromJson(body),
      ),
      'browser.controller.cancel' => BrowserControllerCancelEvent(
        sessionId: sessionId,
        seq: seq,
        payload: BrowserControllerCancelPayload.fromJson(body),
      ),
      'browser.controller.command' => BrowserControllerCommandEvent(
        sessionId: sessionId,
        seq: seq,
        payload: BrowserControllerCommandPayload.fromJson(body),
      ),
      'browser.progress' => BrowserProgressEvent(
        sessionId: sessionId,
        seq: seq,
        payload: BrowserProgressPayload.fromJson(body),
      ),
      'btw.complete' => BtwCompleteEvent(
        sessionId: sessionId,
        seq: seq,
        payload: SideAgentCompletePayload.fromJson(body),
      ),
      'connection.request' => ConnectionRequestEvent(
        sessionId: sessionId,
        seq: seq,
        payload: ConnectionRequestPayload.fromJson(body),
      ),
      'connection.update' => ConnectionUpdateEvent(
        sessionId: sessionId,
        seq: seq,
        payload: ConnectionUpdatePayload.fromJson(body),
      ),
      'cron.changed' => CronChangedEvent(
        sessionId: sessionId,
        seq: seq,
        payload: ChangeSignalPayload.fromJson(body),
      ),
      'display.install.done' => DisplayInstallDoneEvent(
        sessionId: sessionId,
        seq: seq,
        payload: DisplayInstallDonePayload.fromJson(body),
      ),
      'display.install.log' => DisplayInstallLogEvent(
        sessionId: sessionId,
        seq: seq,
        payload: DisplayInstallLogPayload.fromJson(body),
      ),
      'display.lease' => DisplayLeaseEvent(
        sessionId: sessionId,
        seq: seq,
        payload: DisplayLeasePayload.fromJson(body),
      ),
      'display.status' => DisplayStatusEvent(
        sessionId: sessionId,
        seq: seq,
        payload: DisplayStatusPayload.fromJson(body),
      ),
      'error' => HermesErrorEvent(
        sessionId: sessionId,
        seq: seq,
        payload: ErrorPayload.fromJson(body),
      ),
      'gateway.ready' => GatewayReadyEvent(
        sessionId: sessionId,
        seq: seq,
        payload: GatewayReadyPayload.fromJson(body),
      ),
      'layout.apply' => LayoutApplyEvent(
        sessionId: sessionId,
        seq: seq,
        payload: LayoutApplyPayload.fromJson(body),
      ),
      'message.complete' => MessageCompleteEvent(
        sessionId: sessionId,
        seq: seq,
        payload: MessageCompletePayload.fromJson(body),
      ),
      'message.delta' => MessageDeltaEvent(
        sessionId: sessionId,
        seq: seq,
        payload: StreamDeltaPayload.fromJson(body),
      ),
      'message.interim' => MessageInterimEvent(
        sessionId: sessionId,
        seq: seq,
        payload: MessageInterimPayload.fromJson(body),
      ),
      'message.reaction' => MessageReactionEvent(
        sessionId: sessionId,
        seq: seq,
        payload: MessageReactionPayload.fromJson(body),
      ),
      'message.start' => MessageStartEvent(sessionId: sessionId, seq: seq),
      'moa.aggregating' => MoaAggregatingEvent(
        sessionId: sessionId,
        seq: seq,
        payload: MoaAggregatingPayload.fromJson(body),
      ),
      'moa.phase' => MoaPhaseEvent(
        sessionId: sessionId,
        seq: seq,
        payload: MoaPhasePayload.fromJson(body),
      ),
      'moa.progress' => MoaProgressEvent(
        sessionId: sessionId,
        seq: seq,
        payload: MoaProgressPayload.fromJson(body),
      ),
      'moa.reference' => MoaReferenceEvent(
        sessionId: sessionId,
        seq: seq,
        payload: MoaReferencePayload.fromJson(body),
      ),
      'notice' => NoticeEvent(
        sessionId: sessionId,
        seq: seq,
        payload: NoticePayload.fromJson(body),
      ),
      'notification.clear' => NotificationClearEvent(
        sessionId: sessionId,
        seq: seq,
        payload: NotificationClearPayload.fromJson(body),
      ),
      'notification.show' => NotificationShowEvent(
        sessionId: sessionId,
        seq: seq,
        payload: NotificationShowPayload.fromJson(body),
      ),
      'pairing.changed' => PairingChangedEvent(
        sessionId: sessionId,
        seq: seq,
        payload: ChangeSignalPayload.fromJson(body),
      ),
      'pane.reveal' => PaneRevealEvent(
        sessionId: sessionId,
        seq: seq,
