/// A server → client request; answer with a JSON-RPC response carrying [id].
sealed class HermesServerRequest<R extends JsonObject> {
  const HermesServerRequest({required this.id, required this.sessionId});

  /// JSON-RPC request id (`srq-…`); the response must reuse it.
  final String id;

  /// Owning session; empty for app-level requests.
  final String sessionId;

  /// The wire method.
  String get method;

  /// Decodes a request frame, or returns null for a method this client does not know.
  static HermesServerRequest<JsonObject>? fromFrame(
    String id,
    String method,
    Map<String, Object?> params,
  ) {
    final sessionId = params['session_id'] as String? ?? '';
    return switch (method) {
      'approval' => ApprovalServerRequest(
        id: id,
        sessionId: sessionId,
        params: ApprovalRequestParams.fromJson(params),
      ),
      'clarify' => ClarifyServerRequest(
        id: id,
        sessionId: sessionId,
        params: ClarifyRequestParams.fromJson(params),
      ),
      'display.install.sudo' => DisplayInstallSudoServerRequest(
        id: id,
        sessionId: sessionId,
        params: DisplayInstallSudoParams.fromJson(params),
      ),
      'preview.act' => PreviewActServerRequest(
        id: id,
        sessionId: sessionId,
        params: PreviewActRequestParams.fromJson(params),
      ),
      'preview.read' => PreviewReadServerRequest(
        id: id,
        sessionId: sessionId,
        params: ReadRangeRequestParams.fromJson(params),
      ),
      'secret' => SecretServerRequest(
        id: id,
        sessionId: sessionId,
        params: SecretRequestParams.fromJson(params),
      ),
      'sudo' => SudoServerRequest(
        id: id,
        sessionId: sessionId,
        params: SudoRequestParams.fromJson(params),
      ),
      'terminal.read' => TerminalReadServerRequest(
        id: id,
        sessionId: sessionId,
        params: ReadRangeRequestParams.fromJson(params),
      ),
      'tour' => TourServerRequest(
        id: id,
        sessionId: sessionId,
        params: TourRequestParams.fromJson(params),
      ),
      'vault.code' => VaultCodeServerRequest(
        id: id,
        sessionId: sessionId,
        params: VaultCodeRequestParams.fromJson(params),
      ),
      'vault.save_login' => VaultSaveLoginServerRequest(
        id: id,
        sessionId: sessionId,
        params: VaultSaveLoginRequestParams.fromJson(params),
      ),
      'vault.unlock_prompt' => VaultUnlockPromptServerRequest(
        id: id,
        sessionId: sessionId,
        params: VaultUnlockRequestParams.fromJson(params),
      ),
      'window.read' => WindowReadServerRequest(
        id: id,
        sessionId: sessionId,
        params: EmptyRequestParams.fromJson(params),
      ),
      _ => null,
    };
  }
}

