Object _required(Map<String, Object?> json, String key, String owner) =>
    json[key] ?? (throw FormatException('$owner: missing "$key"'));

enum ConnectorRowConnectionStatus {
  pending('pending'),
  active('active'),
  failed('failed'),
  expired('expired'),
  revoked('revoked'),
  inactive('inactive'),

  /// A value this client version does not know.
  $unknown('');

  const ConnectorRowConnectionStatus(this.wire);

  /// The JSON value.
  final String wire;

  /// Decodes [wire]; unknown values map to [$unknown] so newer servers stay readable.
  static ConnectorRowConnectionStatus fromWire(String wire) =>
      values.firstWhere((e) => e.wire == wire, orElse: () => $unknown);
}

enum ConnectorsConnectResultStatus {
  initiated('initiated'),
  settled('settled'),

  /// A value this client version does not know.
  $unknown('');

  const ConnectorsConnectResultStatus(this.wire);

  /// The JSON value.
  final String wire;

  /// Decodes [wire]; unknown values map to [$unknown] so newer servers stay readable.
  static ConnectorsConnectResultStatus fromWire(String wire) =>
      values.firstWhere((e) => e.wire == wire, orElse: () => $unknown);
}

enum WaitBarrierTargetHermesType {
